excels.excel:

EXPORT WITH SHEET="材料领用单", HEADER=true,
    MAPPING={"a":"材料名称","b":"规格型号","c":"领用数量","d":"计量单位","e":"单价","f":"金额","g":"用途"},
    FORMAT={"c":"0","e":"#,##0.00","f":"#,##0.00"},
    FORMULAS={
        F2:'C2*E2',F3:'C3*E3',F4:'C4*E4',F5:'C5*E5',F6:'C6*E6',F7:'C7*E7',
        C8:'SUM(C2:C7)',F8:'SUM(F2:F7)'
    },
    STYLE={
        ROW 8:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center}
    }
